-- 乌鸦子弹, 落石


---@type ParkourGameUtil
local ParkourGameUtil = import("Game.Activity.ParkourGame.ParkourGameUtil")
---@type ParkourGameMgr
local Mgr = import("Game.Activity.ParkourGame.ParkourGameMgr"):GetInstance()

local Parkour_Loader = import('Game.Activity.ParkourGame.Parkour_Loader')

local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

local Mathf = CS.UnityEngine.Mathf
local GameObject = CS.UnityEngine.GameObject
local KTool = CS.Engine.Lib.KTool

local CriWareUtils = import('Game.Entry.CriWareUtilsFix')

---@class BulletRock:TrackTriggerItem
local BulletRock = Class("BulletRock", import("Game.Activity.ParkourGame.MainGame.TrackItems.TrackTriggerItem"))


-- ============================ 

function BulletRock:Type()
    return ParkourGameUtil.TrackItemType.BulletRock
end

--function BulletRock:Start()
--    self.super.Start(self)
--    self.speed = self.speed or 4
--    self.pos = self.transform.localPosition
--    self.move = 0 --减少对transform的操作
--end

function BulletRock:Init(pos, speed, parent)
    self.pos = pos
    --self.speed = speed
    self.accelerate = -Mathf.Abs(speed)
    self.speed = 0
    self.move = 0
    self.move_x = -1
    self.speed_x = -2

    self.transform:SetParent(parent)
    self.transform.localPosition = pos
    CfUtils.SetActive(self.gameObject,true)

    self.fx_88001_stone = self.transform:Find("fx_88001_stone")
    CfUtils.SetActive( self.fx_88001_stone, true )
    ---
    self.shineFXGO = Parkour_Loader.GetInstance():InstanceFXGO("fx_bullet_rock_brock", self.transform )

    self.isHitGround = false
    self.isPlayLogic = false
end



function BulletRock:Reset()
    self.isHitGround = false
    self.isPlayLogic = false
    self.speed = 0
    self.move = 0
    self.move_x = -1
    self.speed_x = -2
    CfUtils.SetActive( self.fx_88001_stone, true )
    CfUtils.SetActive( self.shineFXGO, false )
end


function BulletRock:Tick(deltaTime)

    if self.isHitGround == false then 
        self.speed = self.speed + self.accelerate * deltaTime
        self.move = self.move + deltaTime * self.speed
        self.move_x = self.move_x + self.speed_x * deltaTime
        self.transform.localPosition = Vector3(self.pos.x + self.move_x, self.pos.y + self.move, self.pos.z)
    end
    
    if self:CheckOutRange() then
        self:Recycle()
    end
end


function BulletRock:CheckOutRange()
    return self.pos.y + self.move < -5
end

function BulletRock:PlayLogic(other)
    --print(" trigger:  " .. tostring(other.name) )
    local idComp = KTool.GetComponent(other.gameObject, typeof(CS.Game.Native.Common.ID))
    local isRoleHit = isNotNull(idComp) and idComp.stringId == "hitCollider" -- 猫下面一层的碰撞体, 执行 hit 碰撞
    if isRoleHit then 
        return
    end 

    if self.isPlayLogic == true then 
        return
    end 
    self.isPlayLogic = false

    local isPlayer = other.name == Mgr.player.controller.gameObject.name
    if isPlayer then
        local player = Mgr.player
        if player:OnHit(self.Type())  then
            player:SetRoleFX( "fx_role_injured_jingji", true )  
        end

        CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "crow_stone_12001801" )

        self:Reset()
        self:Recycle()
    else 
        -- 触地:
        ---        
        CoStop(self.co_1)
        self.co_1 = CoStart(function()
            self.isHitGround = true -- 停止下落
            CfUtils.SetActive( self.shineFXGO, true )
            CfUtils.SetActive( self.fx_88001_stone, false )

            CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "crow_stone_12001801" )

            cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.5 ))
            self:Reset()
            self:Recycle()
        end)
        
    end
end


function BulletRock:OnDestroy()
    CoStop(self.co_1)
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end





return BulletRock